              ]
            }
          }
        }
      }
    ],
    "derived": [
      {
        "id": "serviceDuration",
        "type": "integer",
        "unit": "time",
        "expr": {
          "op": "mul",
          "args": [
            {
              "ref": "parameter.serviceHours"
            },
            {
              "literal": 60
            }
          ]
        }
      },
      {
        "id": "trialObserverFeeMinor",
        "type": "integer",
        "unit": "money",
        "expr": {
          "op": "add",
          "args": [
            {
              "op": "mul",
              "args": [
                {
                  "op": "lookup",
                  "table": "_studyFactors",
                  "where": {
                    "id": {
                      "ref": "choice.study"
                    }
                  },
                  "column": "trialCount"
                },
                {
                  "op": "mul",
                  "args": [
                    {
                      "ref": "parameter.observerHourlyRateMinor"
                    },
                    {
                      "ref": "parameter.serviceHours"
                    }
                  ]
