                      "ref": "parameter.observerHourlyRateMinor"
                    },
                    {
                      "ref": "parameter.serviceHours"
                    }
                  ]
                }
              ]
            },
            {
              "op": "mul",
              "args": [
                {
                  "op": "lookup",
                  "table": "_studyFactors",
                  "where": {
                    "id": {
                      "ref": "choice.study"
                    }
                  },
                  "column": "trialCount"
                },
                {
                  "op": "mul",
                  "args": [
                    {
                      "ref": "parameter.observerHourlyRateMinor"
                    },
                    {
                      "ref": "parameter.serviceHours"
                    }
                  ]
                }
              ]
            }
          ]
        }
      },
      {
        "id": "trialRunnerFeeMinor",
        "type": "integer",
        "unit": "money",
        "expr": {
          "op": "add",
          "args": [
            {
              "op": "mul",
              "args": [
                {
                  "op": "lookup",
                  "table": "_studyFactors",
                  "where": {
                    "id": {
                      "ref": "choice.study"
                    }
                  },
                  "column": "trialCount"
                },
                {
                  "op": "mul",
                  "args": [
                    {
                      "ref": "parameter.runnerHourlyRateMinor"
                    },
                    {
                      "ref": "parameter.serviceHours"
                    }
                  ]
                }
              ]
            },
            {
              "op": "mul",
              "args": [
                {
                  "op": "lookup",
                  "table": "_studyFactors",
                  "where": {
                    "id": {
                      "ref": "choice.study"
                    }
                  },
                  "column": "trialCount"
                },
                {
                  "op": "mul",
                  "args": [
                    {
                      "ref": "parameter.runnerHourlyRateMinor"
                    },
                    {
                      "ref": "parameter.serviceHours"
                    }
                  ]
                }
              ]
            }
          ]
        }
      },
      {
        "id": "studyFeeMinor",
        "type": "integer",
        "unit": "money",
        "expr": {
          "op": "add",
          "args": [
            {
              "ref": "derived.trialObserverFeeMinor"
            },
            {
              "ref": "derived.trialRunnerFeeMinor"
            },
            {
              "op": "mul",
              "args": [
                {
                  "op": "lookup",
                  "table": "_studyFactors",
                  "where": {
                    "id": {
                      "ref": "choice.study"
                    }
                  },
                  "column": "auditCount"
                },
                {
                  "ref": "parameter.auditFeeMinor"
                }
              ]
            }
          ]
        }
      },
      {
        "id": "studyDuration",
        "type": "integer",
        "unit": "time",
        "expr": {
          "op": "add",
          "args": [
            {
              "op": "mul",
              "args": [
                {
                  "op": "lookup",
                  "table": "_studyFactors",
                  "where": {
                    "id": {
                      "ref": "choice.study"
                    }
                  },
                  "column": "auditCount"
                },
                {
                  "ref": "parameter.auditDuration"
                }
              ]
            },
            {
              "op": "mul",
              "args": [
                {
                  "op": "lookup",
                  "table": "_studyFactors",
                  "where": {
                    "id": {
                      "ref": "choice.study"
                    }
                  },
                  "column": "trialCount"
                },
                {
                  "op": "mul",
                  "args": [
                    {
                      "op": "lookup",
                      "table": "_booleans",
                      "where": {
                        "flag": {
                          "op": "gte",
                          "args": [
                            {
                              "ref": "parameter.trialAnswerTime"
                            },
                            {
                              "ref": "parameter.currentTime"
                            }
                          ]
                        }
                      },
                      "column": "count"
                    },
                    {
                      "op": "sub",
                      "args": [
                        {
                          "ref": "parameter.trialAnswerTime"
                        },
                        {
                          "ref": "parameter.currentTime"
                        }
                      ]
                    }
                  ]
                }
              ]
            }
          ]
        }
      },
      {
        "id": "answerTime",
        "type": "integer",
        "unit": "time",
        "expr": {
          "op": "add",
          "args": [
            {
              "ref": "parameter.currentTime"
            },
            {
              "ref": "derived.studyDuration"
            }
          ]
        }
      },
      {
        "id": "futurePayoffMinor",
        "type": "integer",
        "unit": "money",
        "expr": {
          "op": "add",
          "args": [
            {
              "literal": 0
            },
            {
              "op": "mul",
              "args": [
                {
                  "op": "mul",
                  "args": [
                    {
                      "ref": "parameter.futureDinnerCount"
                    },
                    {
                      "op": "lookup",
                      "table": "_responseFactors",
                      "where": {
                        "id": {
                          "ref": "choice.response"
                        }
                      },
                      "column": "runnerCount"
                    }
                  ]
                },
                {
                  "op": "add",
                  "args": [
                    {
                      "op": "mul",
                      "args": [
                        {
                          "ref": "scenario.upsideCount"
                        },
                        {
                          "ref": "parameter.upsidePerDinnerMinor"
                        }
                      ]
                    },
                    {
                      "op": "mul",
                      "args": [
                        {
                          "ref": "scenario.downsideCount"
                        },
                        {
                          "ref": "parameter.downsidePerDinnerMinor"
                        }
                      ]
                    }
                  ]
                }
              ]
            }
          ]
        }
      }
    ],
